package com.kooo.evcam.playback;

import androidx.annotation.Nullable;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Computes aspect-preserving 2D scale+translate parameters for zooming single camera quadrants
 * out of B-Composite {@code _combined.mp4} recordings generated by {@code MultiCameraCompositor}.
 *
 * <p>{@code MultiCameraCompositor} lays out existing cameras in fixed order
 * {@code left, back, right, front} across {@code columns=2} on E5 (left=top-left,
 * back=top-right, right=bottom-left, front=bottom-right).
 */
public final class CompositeQuadrantMath {

    public static final List<String> COMPOSITE_ORDER = Collections.unmodifiableList(
            Arrays.asList(
                    VideoGroup.POSITION_LEFT,
                    VideoGroup.POSITION_BACK,
                    VideoGroup.POSITION_RIGHT,
                    VideoGroup.POSITION_FRONT));

    public static final class TransformSpec {
        public final float scaleX;
        public final float scaleY;
        public final float translateX;
        public final float translateY;

        public TransformSpec(float scaleX, float scaleY, float translateX, float translateY) {
            this.scaleX = scaleX;
            this.scaleY = scaleY;
            this.translateX = translateX;
            this.translateY = translateY;
        }
    }

    private CompositeQuadrantMath() {}

    /**
     * Maps normalized TextureView touch coordinates (0..1, 0..1) inside an unzoomed 2x2 composite
     * frame to the camera position at that quadrant.
     */
    @Nullable
    public static String quadrantAtNormalized(float nx, float ny) {
        if (nx < 0f || nx > 1f || ny < 0f || ny > 1f) {
            return null;
        }
        boolean leftHalf = nx < 0.5f;
        boolean topHalf = ny < 0.5f;
        if (topHalf) {
            return leftHalf ? VideoGroup.POSITION_LEFT : VideoGroup.POSITION_BACK;
        } else {
            return leftHalf ? VideoGroup.POSITION_RIGHT : VideoGroup.POSITION_FRONT;
        }
    }

    /**
     * Computes scale + translation transform relative to a {@code TextureView}'s default
     * stretched coordinate space {@code [0..viewW, 0..viewH]}.
     *
     * @param position target camera ({@code front}/{@code back}/{@code left}/{@code right}),
     *                 or {@code null}/{@code combined} to fit the entire mosaic.
     */
    public static TransformSpec computeTransform(float viewW,
                                                 float viewH,
                                                 float videoW,
                                                 float videoH,
                                                 @Nullable String position) {
        if (viewW <= 0f || viewH <= 0f || videoW <= 0f || videoH <= 0f) {
            return new TransformSpec(1f, 1f, 0f, 0f);
        }
        int slotIndex = position == null ? -1 : COMPOSITE_ORDER.indexOf(position);
        if (slotIndex < 0) {
            float fitScale = Math.min(viewW / videoW, viewH / videoH);
            float rw = videoW * fitScale;
            float rh = videoH * fitScale;
            return new TransformSpec(
                    rw / viewW,
                    rh / viewH,
                    (viewW - rw) * 0.5f,
                    (viewH - rh) * 0.5f);
        }

        final int columns = 2;
        final int rows = 2;
        int col = slotIndex % columns;
        int row = slotIndex / columns;

        float tileW = videoW / columns;
        float tileH = videoH / rows;
        float tileFitScale = Math.min(viewW / tileW, viewH / tileH);

        float fullScaledW = videoW * tileFitScale;
        float fullScaledH = videoH * tileFitScale;
        float scaleX = fullScaledW / viewW;
        float scaleY = fullScaledH / viewH;

        float tileCenterX = (col + 0.5f) * tileW * tileFitScale;
        float tileCenterY = (row + 0.5f) * tileH * tileFitScale;
        float tx = viewW * 0.5f - tileCenterX;
        float ty = viewH * 0.5f - tileCenterY;
        return new TransformSpec(scaleX, scaleY, tx, ty);
    }
}
